-- ACCT-001: immutable balanced USD entries, with beneficiary and fund held per entry.
CREATE TABLE tt_gl_accounts(code TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('asset','liability','income','expense','equity')),fund TEXT NOT NULL CHECK(fund IN ('operating','deposit','both')),cash INTEGER NOT NULL DEFAULT 0 CHECK(cash IN (0,1)),created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE VIEW tt_gl_chart AS SELECT column1 AS code,column2 AS name,column3 AS kind,column4 AS fund,column5 AS cash,column6 AS created_by,column7 AS created_at FROM (VALUES ('cash','Recorded external cash','asset','both',1,'migration','2026-10-22'),('receivable','Lease receivable','asset','operating',0,'migration','2026-10-22'),('lease_income','Lease income','income','operating',0,'migration','2026-10-22'),('deposit_liability','Resident security deposits','liability','deposit',0,'migration','2026-10-22'),('expense','Property expenses','expense','operating',0,'migration','2026-10-22'),('payable','Vendor payables','liability','operating',0,'migration','2026-10-22'),('fee_expense','Management expenses including recorded fee tax','expense','operating',0,'migration','2026-10-22'),('fee_payable','Management fee payables','liability','operating',0,'migration','2026-10-22'),('tax_payable','Lease tax payable','liability','operating',0,'migration','2026-10-22'),('contribution','Owner contributions','equity','operating',0,'migration','2026-10-22'),('opening_equity','Opening balance equity','equity','both',0,'migration','2026-10-22')) UNION ALL SELECT * FROM tt_gl_accounts;
CREATE TABLE tt_journal(id TEXT PRIMARY KEY,day TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),property_id TEXT REFERENCES tt_properties(id),owner_key TEXT NOT NULL,tenancy_id TEXT REFERENCES tt_tenancies(id),vendor_id TEXT REFERENCES tt_vendors(id),fund TEXT NOT NULL CHECK(fund IN ('operating','deposit')),source_kind TEXT NOT NULL,source_id TEXT NOT NULL,reference TEXT NOT NULL,lines TEXT NOT NULL CHECK(json_valid(lines)),reversal_of TEXT UNIQUE REFERENCES tt_journal(id),recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(source_kind,source_id,owner_key));
CREATE VIEW tt_journal_lines AS SELECT j.*,CAST(l.key AS INTEGER) AS position,json_extract(l.value,'$.account') AS account,json_extract(l.value,'$.debit') AS debit_cents,json_extract(l.value,'$.credit') AS credit_cents FROM tt_journal j,json_each(j.lines) l;
CREATE INDEX tt_journal_owner ON tt_journal(owner_key,property_id,day);
CREATE INDEX tt_journal_tenancy ON tt_journal(tenancy_id,day);
CREATE TRIGGER tt_journal_balanced BEFORE INSERT ON tt_journal BEGIN
 SELECT CASE WHEN json_type(NEW.lines)<>'array' OR json_array_length(NEW.lines)<2 OR json_array_length(NEW.lines)>100 OR EXISTS(SELECT 1 FROM json_each(NEW.lines) l LEFT JOIN tt_gl_chart a ON a.code=json_extract(l.value,'$.account') WHERE a.code IS NULL OR (a.fund<>'both' AND a.fund<>NEW.fund) OR json_type(l.value,'$.debit') IS NOT 'integer' OR json_type(l.value,'$.credit') IS NOT 'integer' OR json_extract(l.value,'$.debit')<0 OR json_extract(l.value,'$.credit')<0 OR json_extract(l.value,'$.debit')>100000000 OR json_extract(l.value,'$.credit')>100000000 OR (json_extract(l.value,'$.debit')=0)=(json_extract(l.value,'$.credit')=0)) OR (SELECT SUM(json_extract(value,'$.debit')-json_extract(value,'$.credit')) FROM json_each(NEW.lines))<>0 THEN RAISE(ABORT,'unbalanced_journal') END;
 SELECT CASE WHEN NEW.reversal_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tt_journal o WHERE o.id=NEW.reversal_of AND o.reversal_of IS NULL AND o.property_id IS NEW.property_id AND o.owner_key=NEW.owner_key AND o.tenancy_id IS NEW.tenancy_id AND o.vendor_id IS NEW.vendor_id AND o.fund=NEW.fund AND NEW.lines=(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(o.lines))) THEN RAISE(ABORT,'invalid_reversal') END;
 -- An entry is balanced within one owner/property/fund. Cash cannot be borrowed from any other bucket.
 SELECT CASE WHEN COALESCE((SELECT SUM(l.debit_cents-l.credit_cents) FROM tt_journal_lines l JOIN tt_gl_chart a ON a.code=l.account WHERE a.cash=1 AND l.property_id IS NEW.property_id AND l.owner_key=NEW.owner_key AND l.fund=NEW.fund),0)+(SELECT COALESCE(SUM(json_extract(l.value,'$.debit')-json_extract(l.value,'$.credit')),0) FROM json_each(NEW.lines) l JOIN tt_gl_chart a ON a.code=json_extract(l.value,'$.account') WHERE a.cash=1)<0 THEN RAISE(ABORT,'insufficient_owner_funds') END;
END;
CREATE TRIGGER tt_journal_kept BEFORE DELETE ON tt_journal BEGIN SELECT RAISE(ABORT,'Journal entries are never deleted'); END;
CREATE TRIGGER tt_journal_immutable BEFORE UPDATE ON tt_journal WHEN NOT (EXISTS(SELECT 1 FROM tt_erasure_work w WHERE w.tenancy_id=OLD.tenancy_id) AND NEW.reference=OLD.id AND NEW.id=OLD.id AND NEW.day=OLD.day AND NEW.currency=OLD.currency AND NEW.property_id IS OLD.property_id AND NEW.owner_key=OLD.owner_key AND NEW.tenancy_id IS OLD.tenancy_id AND NEW.vendor_id IS OLD.vendor_id AND NEW.fund=OLD.fund AND NEW.source_kind=OLD.source_kind AND NEW.source_id=OLD.source_id AND NEW.lines=OLD.lines AND NEW.reversal_of IS OLD.reversal_of AND NEW.recorded_by=OLD.recorded_by AND NEW.recorded_at=OLD.recorded_at) BEGIN SELECT RAISE(ABORT,'Journal entries are never edited'); END;
CREATE TRIGGER tt_gl_account_immutable BEFORE UPDATE ON tt_gl_accounts BEGIN SELECT RAISE(ABORT,'Chart accounts are never rewritten; add a new account'); END;
CREATE TRIGGER tt_gl_account_kept BEFORE DELETE ON tt_gl_accounts BEGIN SELECT RAISE(ABORT,'Chart accounts are never deleted'); END;
ALTER TABLE tt_adjustments ADD COLUMN posting_day TEXT;
CREATE TRIGGER tt_adjustment_posting_day_fixed BEFORE UPDATE OF posting_day ON tt_adjustments WHEN NEW.posting_day IS NOT OLD.posting_day BEGIN SELECT RAISE(ABORT,'Accounting posting dates are never edited'); END;
-- Sources are projected once, inside the source transaction. Dated owner shares and exact cent allocation
-- are frozen in the resulting entry. Legacy unit-less records retain an opaque recorded-owner key.
CREATE VIEW tt_gl_sources AS
 SELECT q.id AS sid,'charge' AS kind,q.due_date AS day,u.property_id,t.id AS tenancy_id,NULL AS vendor_id,NULL AS owner_hint,q.amount_cents AS amount_cents,'receivable' AS debit,CASE WHEN q.tax_rule_id IS NULL THEN 'lease_income' ELSE 'tax_payable' END AS credit,q.reference,q.created_at AS at,q.currency FROM tt_charges q JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT r.id,'receipt',r.received_date,u.property_id,t.id,NULL,NULL,r.amount_cents,'cash','receivable',r.reference,r.created_at,r.currency FROM tt_receipts r JOIN tt_charges q ON q.id=r.charge_id JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT a.id,'reduction',COALESCE(a.posting_day,substr(a.at,1,10)),u.property_id,t.id,NULL,NULL,a.amount_cents,CASE WHEN q.tax_rule_id IS NULL THEN 'lease_income' ELSE 'tax_payable' END,'receivable',a.reason,a.at,a.currency FROM tt_adjustments a JOIN tt_charges q ON q.id=a.charge_id JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT x.id,'bill',x.day,x.property_id,NULL,COALESCE(json_extract(rev.terms,'$.vendorId'),b.vendor_id),x.owner_id,x.amount_cents,'expense','payable',b.id,b.created_at,'USD' FROM tt_bill_expenses x JOIN tt_bills b ON b.id=x.bill_id JOIN tt_bill_revisions rev ON rev.bill_id=x.bill_id AND rev.version=x.version
 UNION ALL SELECT f.id,'fee',f.day,f.property_id,NULL,NULL,f.owner_id,f.amount_cents+f.tax_cents,'fee_expense','fee_payable',f.id,f.created_at,'USD' FROM tt_fees f;
CREATE VIEW tt_gl_allocations AS
 SELECT s.*,COALESCE(s.owner_hint,h.owner_id,'lease-owner:'||s.tenancy_id) AS beneficiary,
 CASE WHEN h.owner_id IS NULL THEN s.amount_cents ELSE CAST(s.amount_cents*h.share_bp/10000 AS INTEGER)+CASE WHEN h.owner_id=(SELECT owner_id FROM tt_ownership_shares WHERE set_id=h.set_id ORDER BY share_bp DESC,position LIMIT 1) THEN s.amount_cents-(SELECT SUM(CAST(s.amount_cents*z.share_bp/10000 AS INTEGER)) FROM tt_ownership_shares z WHERE z.set_id=h.set_id) ELSE 0 END END AS allocated
 FROM tt_gl_sources s LEFT JOIN tt_ownership_shares h ON s.owner_hint IS NULL AND h.set_id=(SELECT id FROM tt_ownership_sets WHERE property_id=s.property_id AND effective_from<=s.day ORDER BY effective_from DESC LIMIT 1) WHERE s.currency='USD';
CREATE VIEW tt_gl_native AS SELECT 'native:'||kind||':'||sid||':'||beneficiary AS id,day,property_id,beneficiary AS owner_key,tenancy_id,vendor_id,'operating' AS fund,kind AS source_kind,sid AS source_id,reference,
 json_array(json_object('account',CASE WHEN allocated>0 THEN debit ELSE credit END,'debit',ABS(allocated),'credit',0),json_object('account',CASE WHEN allocated>0 THEN credit ELSE debit END,'debit',0,'credit',ABS(allocated))) AS lines,'native:'||kind AS recorded_by,at AS recorded_at FROM tt_gl_allocations WHERE allocated<>0;
INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native ORDER BY recorded_at,source_kind,id;
-- A pre-existing bill revision already superseded an earlier payable before this migration existed.
-- Retain both historical expenses and their inverse, leaving only the current payable outstanding.
INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,reversal_of,recorded_by,recorded_at)
 SELECT 'bill-revision:'||j.id,j.day,j.property_id,j.owner_key,j.tenancy_id,j.vendor_id,j.fund,'bill_reversal',j.id,j.id,(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(j.lines)),j.id,'native:bill_revision',COALESCE((SELECT prepared_at FROM tt_bill_revisions WHERE bill_id=x.bill_id AND version=x.version+1),b.created_at) FROM tt_journal j JOIN tt_bill_expenses x ON x.id=j.source_id JOIN tt_bills b ON b.id=x.bill_id WHERE j.source_kind='bill' AND x.version<b.version;

CREATE TRIGGER tt_charges_journal AFTER INSERT ON tt_charges BEGIN INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native WHERE source_id=NEW.id AND source_kind='charge'; END;
CREATE TRIGGER tt_receipts_journal AFTER INSERT ON tt_receipts BEGIN INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native WHERE source_id=NEW.id AND source_kind='receipt'; END;
CREATE TRIGGER tt_adjustments_journal AFTER INSERT ON tt_adjustments BEGIN INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native WHERE source_id=NEW.id AND source_kind='reduction'; END;
CREATE TRIGGER tt_bill_expenses_journal AFTER INSERT ON tt_bill_expenses BEGIN INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native WHERE source_id=NEW.id AND source_kind='bill'; END;
CREATE TRIGGER tt_fees_journal AFTER INSERT ON tt_fees BEGIN INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native WHERE source_id=NEW.id AND source_kind='fee'; END;
CREATE TRIGGER tt_journal_period BEFORE INSERT ON tt_journal WHEN EXISTS(SELECT 1 FROM tt_period_closes WHERE month=substr(NEW.day,1,7) AND reopened_at IS NULL) BEGIN SELECT RAISE(ABORT,'period_closed'); END;
CREATE TABLE tt_receipt_reversals(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL UNIQUE REFERENCES tt_receipts(id),day TEXT NOT NULL,reference TEXT NOT NULL,reason TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TRIGGER tt_receipt_reversal_kept BEFORE DELETE ON tt_receipt_reversals BEGIN SELECT RAISE(ABORT,'Receipt reversals are never deleted'); END;
CREATE TRIGGER tt_receipt_reversal_immutable BEFORE UPDATE ON tt_receipt_reversals WHEN NOT(EXISTS(SELECT 1 FROM tt_receipts r JOIN tt_charges q ON q.id=r.charge_id JOIN tt_erasure_work w ON w.tenancy_id=q.tenancy_id WHERE r.id=OLD.receipt_id) AND NEW.reference=OLD.id AND NEW.reason='Retained accounting record' AND NEW.id=OLD.id AND NEW.receipt_id=OLD.receipt_id AND NEW.day=OLD.day AND NEW.recorded_by=OLD.recorded_by AND NEW.recorded_at=OLD.recorded_at) BEGIN SELECT RAISE(ABORT,'Receipt reversals are never edited'); END;
CREATE VIEW tt_net_receipts AS SELECT r.*,NULL AS reversal_of FROM tt_receipts r UNION ALL SELECT x.id,r.charge_id,-r.amount_cents,x.day,x.reference,x.recorded_at,r.currency,r.method,r.id FROM tt_receipt_reversals x JOIN tt_receipts r ON r.id=x.receipt_id;
CREATE TRIGGER tt_receipt_reverse_journal AFTER INSERT ON tt_receipt_reversals BEGIN
 INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,reversal_of,recorded_by,recorded_at)
 SELECT NEW.id||':'||j.id,NEW.day,j.property_id,j.owner_key,j.tenancy_id,j.vendor_id,j.fund,'receipt_reversal',NEW.id,NEW.reference,(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(j.lines)),j.id,NEW.recorded_by,NEW.recorded_at FROM tt_journal j WHERE j.source_kind='receipt' AND j.source_id=NEW.receipt_id;
END;
CREATE TRIGGER tt_receipt_reversal_period BEFORE INSERT ON tt_receipt_reversals WHEN EXISTS(SELECT 1 FROM tt_period_closes WHERE month=substr(NEW.day,1,7) AND reopened_at IS NULL) BEGIN SELECT RAISE(ABORT,'period_closed'); END;
INSERT INTO tt_role_actions(role,action) VALUES ('portfolio_manager','journal.post'),('bookkeeper','journal.post'),('portfolio_manager','journal.reverse'),('bookkeeper','journal.reverse'),('portfolio_manager','rent.reverse-receipt'),('bookkeeper','rent.reverse-receipt');

ALTER TABLE tt_period_closes ADD COLUMN journal_statement TEXT NOT NULL DEFAULT '[]';
CREATE TRIGGER tt_close_journal_kept BEFORE UPDATE OF journal_statement ON tt_period_closes WHEN NEW.journal_statement<>OLD.journal_statement BEGIN SELECT RAISE(ABORT,'A close journal statement is never edited'); END;
CREATE TRIGGER tt_bill_revise_journal AFTER UPDATE OF version ON tt_bills WHEN NEW.version<>OLD.version BEGIN
 INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,reversal_of,recorded_by,recorded_at)
 SELECT 'bill-revision:'||j.id,OLD.day,j.property_id,j.owner_key,j.tenancy_id,j.vendor_id,j.fund,'bill_reversal',j.id,j.id,(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(j.lines)),j.id,NEW.revised_by,NEW.created_at FROM tt_journal j JOIN tt_bill_expenses x ON x.id=j.source_id WHERE j.source_kind='bill' AND x.bill_id=OLD.id AND x.version=OLD.version;
END;

CREATE TRIGGER tt_chart_builtin BEFORE INSERT ON tt_gl_accounts WHEN NEW.code IN (SELECT code FROM tt_gl_chart WHERE created_by='migration') BEGIN SELECT RAISE(ABORT,'built_in_account'); END;
